window.docContents[69].resolve({"/Equiv/#Hoare-Logic--Equiv___-Program-Equivalence--Behavioral-Equivaleence--Simple-Examples":{"contents":"namespace Com\n\n\n\n\ntheorem skip_left {c : Com} : (imp { skip; ~c }).Equiv c := by\n  sorry\n\n\nProve that adding a skip after a command also results in an\nequivalent program.theorem skip_right {c : Com} : (imp { ~c; skip }).Equiv c := by\n  sorry\n\n\n\n\ntheorem if_true_simple {c₁ c₂ : Com} : (imp {if (true) {~c₁} else {~c₂}}).Equiv c₁ := by\n  rw [equiv_def]\n  intro st st'\n  constructor\n  · intro h\n    inversion h with\n    | ifTrue hb hc => exact hc\n    | ifFalse hb hc => simp at hb\n  · intro h\n    apply EvalR.ifTrue _ h\n    simp\n\n\n\n\nThe to_verso script seems to use \\[\\] blocks, but these seem to\ncause problems with the tilde. Currently skipping them and just using\nbackticks.\n\n\n\n\n\ntheorem if_true {b : Bexp} {c₁ c₂ : Com} (hb : b.Equiv (bexp {true})) :\n    (imp {if (~b) {~c₁} else {~c₂}}).Equiv c₁ := by\n  rw [equiv_def]\n  rw [Bexp.equiv_def] at hb\n  intro st st'\n  constructor\n  · intro h\n    inversion h with\n    | ifTrue hb' hc =>\n      exact hc\n    | ifFalse hb' hc =>\n      rw [hb] at hb'\n      simp at hb'\n  · intro h\n    apply EvalR.ifTrue _ h\n    rw [hb]\n    simp\n\n\ntheorem if_false {b : Bexp} {c₁ c₂ : Com} (hb : b.Equiv (bexp {false})) :\n    (imp {if (~b) {~c₁} else {~c₂}}).Equiv c₂ := by\n  sorry\n\n\nShow that we can swap the branches of an if if we also negate its\ncondition.theorem swap_if_branches {b : Bexp} {c₁ c₂ : Com} :\n    (imp {if (~b) {~c₁} else {~c₂}}).Equiv\n    (imp {if (¬ ~b) {~c₂} else {~c₁}}) := by\n  sorry\n\n\n\n\n\n\ntheorem while_false_equiv {b : Bexp} {c : Com} (hb : b.Equiv (bexp {false})) :\n    (imp {while (~b) {~c}}).Equiv\n    (imp {skip}) := by\n  rw [equiv_def]\n  rw [Bexp.equiv_def] at hb\n  intro st st''\n  constructor\n  · intro h\n    inversion h with\n    | whileFalse => exact EvalR.skip\n    | whileTrue st' hb' hc hloop =>\n      simp [hb] at hb'\n  · intro h\n    inversion h\n    apply EvalR.whileFalse\n    simp [hb]\n\n\nWrite an informal proof of while_false_equiv.\n\n\n\n\n\ntheorem while_true_nonterm {b : Bexp} {c : Com} {st st' : State} (hb : b.Equiv (bexp {true})) :\n    ¬ st =[ while (~b) {~c} ]=> st' := by\n  sorry -- heq says that different commands are equal\n\n\nExplain what the lemma while_true_nonterm means in English.\n\nProve the following theorem. Hint: You'll want to use\nwhile_true_nonterm here.theorem while_true {b : Bexp} {c : Com} (hb : b.Equiv (bexp {true})) :\n    (imp {while (~b) {~c}}).Equiv\n    (imp {while (true) {skip}}) := by\n  sorry\n\n\n\n\ntheorem loop_unrolling {b : Bexp} {c : Com} :\n    (imp {while (~b) {~c}}).Equiv\n    (imp {\n      if (~b) {~c} else {skip};\n      while (~b) {~c}\n    }) := by\n  sorry\n\n\nLeaving out optional exercise seq_assoc for now.\n\n\n\ntheorem identity_assignment {X : Ident} :\n    (imp {X := X}).Equiv\n    (imp {skip}) := by\n  rw [equiv_def]\n  intro st st'\n  constructor\n  · intro h\n    inversion h with\n    | asgn n h =>\n      subst h\n      simp only [Aexp.eval_id, TotalMap.update_same]\n      exact Com.EvalR.skip\n  · intro h\n    inversion h\n    suffices st =[ X := X ]=> X →ₜ st[X] ; st by\n      simp only [TotalMap.update_same] at this\n      exact this\n    apply Com.EvalR.asgn\n    simp\n\n\ntheorem assign_equiv {X : Ident} {a : Aexp} (ha : Aexp.Equiv (aexp {X}) a) :\n    (imp {skip}).Equiv\n    (imp {X := ~a}) := by\n  sorry\n\n\nLeaving out optional exercise equiv_classes for now.\n\n","context":"Hoare Logic\u0009Equiv: Program Equivalence\u0009Behavioral Equivaleence","header":"4.1.2. Simple Examples","id":"/Equiv/#Hoare-Logic--Equiv___-Program-Equivalence--Behavioral-Equivaleence--Simple-Examples"}});